// Preferences are shared across careers, saved with the student's account progress.
function validFocusMinutes(value,fallback,max){const n=Number(value);return Number.isInteger(n)&&n>=1&&n<=max?n:fallback}
function focusPreferences(){const p=state.focusPreferences||{};return {focus:validFocusMinutes(p.focus,25,180),pause:validFocusMinutes(p.pause,5,60)}}
let focusMode='focus',focusRunning=false,focusEnd=0,focusTotal=focusPreferences().focus*60,focusRemaining=focusTotal;
function paintFocus(){const p=focusPreferences();$('#clock').textContent=String(Math.floor(focusRemaining/60)).padStart(2,'0')+':'+String(focusRemaining%60).padStart(2,'0');$('#timer-label').textContent=focusMode==='focus'?`Sessão de foco · ${p.focus} minutos`:`Pausa · ${p.pause} minutos`;$('#timer').textContent=focusRunning?'Ⅱ Pausar':focusMode==='focus'?'▶ Iniciar foco':'▶ Iniciar pausa';for(const mode of ['focus','pause']){const input=$('#'+mode+'-minutes');if(document.activeElement!==input)input.value=p[mode]}}
function focusTick(){if(focusRunning){focusRemaining=Math.max(0,Math.ceil((focusEnd-Date.now())/1000));if(focusRemaining===0){focusRunning=false;focusMode=focusMode==='focus'?'pause':'focus';focusTotal=focusPreferences()[focusMode]*60;focusRemaining=focusTotal;toast(focusMode==='pause'?'Sessão concluída! Inicie sua pausa quando quiser.':'Pausa concluída. Inicie a próxima sessão quando quiser.')}}paintFocus()}
function setFocusMinutes(mode,value){const max=mode==='focus'?180:60,n=Number(value);if(!Number.isInteger(n)||n<1||n>max){toast(`Escolha de 1 a ${max} minutos.`);$('#'+mode+'-minutes').value=focusPreferences()[mode];return}focusTick();const p=focusPreferences();if(p[mode]===n)return;state.focusPreferences={...p,[mode]:n};if(focusMode===mode){const elapsed=focusTotal-focusRemaining;focusTotal=n*60;focusRemaining=Math.max(0,focusTotal-elapsed);focusEnd=Date.now()+focusRemaining*1000;if(!focusRemaining){focusRunning=false;toast('O tempo escolhido já foi cumprido. Reinicie para uma nova sessão.')}}save();paintFocus()}
for(const mode of ['focus','pause']){const input=$('#'+mode+'-minutes');input.onchange=()=>setFocusMinutes(mode,input.value);$('#'+mode+'-apply').onclick=()=>setFocusMinutes(mode,input.value);for(const delta of [-5,5])$('#'+mode+(delta<0?'-less':'-more')).onclick=()=>setFocusMinutes(mode,Math.min(mode==='focus'?180:60,Math.max(1,focusPreferences()[mode]+delta)))}
$('#timer').onclick=()=>{focusTick();if(focusRemaining===0){focusTotal=focusPreferences()[focusMode]*60;focusRemaining=focusTotal}focusRunning=!focusRunning;if(focusRunning)focusEnd=Date.now()+focusRemaining*1000;paintFocus()};
$('#reset').onclick=()=>{focusRunning=false;focusMode='focus';focusTotal=focusPreferences().focus*60;focusRemaining=focusTotal;paintFocus()};
function reloadFocusPreferences(){focusRunning=false;focusMode='focus';focusTotal=focusPreferences().focus*60;focusRemaining=focusTotal;paintFocus()}
paintFocus();setInterval(focusTick,500);
